ValidationRule.errorConditionFormula:
AND(
    NOT($Setup.Case_Validation_Bypass__c.Bypass_Validation__c),
    AND(
    NOT(ISBLANK(Visitor_Email_Search__c)),
    NOT(
        REGEX(
            Visitor_Email_Search__c,
            "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"
        )
    )
)
)
